// Verify the HMAC the trigger-workflow Edge Function attached, then reject replays.
// Same HMAC-SHA256 as supabase/functions/_shared/hmac.ts. Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto
// (set on the n8n container) and env access (N8N_BLOCK_ENV_ACCESS_IN_NODE=false).
const crypto = require('crypto');
const item = $input.first().json;
const headers = item.headers || {};
const sig = headers['x-signature'];
const ts = headers['x-timestamp'];
const secret = $env.N8N_WEBHOOK_SECRET;
if (!sig || !ts || !secret) { throw new Error('missing signature/timestamp/secret'); }
if (Math.abs(Date.now() - Number(ts)) > 5 * 60 * 1000) { throw new Error('stale timestamp (replay?)'); }
// The Edge Function signed `${ts}.${JSON.stringify(body)}`; re-stringify the parsed body.
const raw = ts + '.' + JSON.stringify(item.body);
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
if (expected !== sig) { throw new Error('bad signature'); }
// Pass the application row downstream.
return [{ json: item.body.data }];

// Parse the model's JSON and shape the row update.
const application = $('Verify signature').first().json;
const content = ($input.first().json.choices && $input.first().json.choices[0] && $input.first().json.choices[0].message.content) || '{}';
let screening = {};
try { screening = JSON.parse(content); } catch (e) { screening = { score: null, error: 'unparseable' }; }
return [{ json: { id: application.id, email: application.email, full_name: application.full_name, ai_score: screening.score ?? null, status: 'screened', screening } }];

